-- 1. Analiticas base y Correccion Masiva
CREATE OR REPLACE FUNCTION fn_auditar_ruts_masivo() RETURNS TABLE(identificador VARCHAR, msj TEXT) AS $$
DECLARE rec RECORD;
BEGIN FOR rec IN SELECT RUN FROM Cliente LOOP IF rec.RUN NOT LIKE '%-K' AND rec.RUN NOT SIMILAR TO '%-[0-9]' THEN identificador := rec.RUN; msj := 'Advertencia: DV incorrecto.'; RETURN NEXT; END IF; END LOOP; END; $$ LANGUAGE plpgsql;

-- BLOQUE GENERADOR DE FUNCIONES CRUD DINAMICAS
DO $crud$
DECLARE t_name text;
BEGIN FOR t_name IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' AND tablename IN ('region', 'cliente', 'empresa', 'producto', 'venta') LOOP
EXECUTE format('CREATE OR REPLACE FUNCTION fn_delete_%I(p_id TEXT) RETURNS VOID AS $f$ BEGIN EXECUTE ''DELETE FROM %I WHERE '' || (SELECT a.attname FROM pg_index i JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = ANY(i.indkey) WHERE i.indrelid = ''%I''::regclass LIMIT 1) || '' = $1'' USING p_id; END; $f$ LANGUAGE plpgsql;', t_name, t_name, t_name); END LOOP; END; $crud$;

-- GRUPO 1: Consolidacion Temporal
CREATE OR REPLACE FUNCTION fn_cant_clientes_compraron_producto(p_producto VARCHAR, p_f_inicio DATE, p_f_fin DATE) RETURNS INT AS $$ DECLARE v_cant INT; BEGIN SELECT COUNT(DISTINCT co.Cliente_id) INTO v_cant FROM Comprar co JOIN Producto p ON co.Producto_id = p.ID JOIN Vender ve ON co.Venta_id = ve.Venta_id WHERE p.Nombre ILIKE '%' || p_producto || '%' AND ve.Fecha BETWEEN p_f_inicio AND p_f_fin; RETURN COALESCE(v_cant, 0); END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_clientes_compraron_producto(p_producto VARCHAR, p_f_inicio DATE, p_f_fin DATE) RETURNS TABLE(run_cliente VARCHAR, nombre_cliente TEXT) AS $$ BEGIN RETURN QUERY SELECT DISTINCT c.RUN, (c.Nombre || ' ' || c.Apellido)::TEXT FROM Cliente c JOIN Comprar co ON c.RUN = co.Cliente_id JOIN Producto p ON co.Producto_id = p.ID JOIN Vender ve ON co.Venta_id = ve.Venta_id WHERE p.Nombre ILIKE '%' || p_producto || '%' AND ve.Fecha BETWEEN p_f_inicio AND p_f_fin; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_compras_mes_actual_cliente(p_run_cliente VARCHAR) RETURNS TABLE(run VARCHAR, total_compras BIGINT, total_pagado NUMERIC, corresponde_descuento BOOLEAN) AS $$ BEGIN RETURN QUERY SELECT c.RUN, COUNT(v.ID), SUM(v.Total)::NUMERIC, (COUNT(v.ID) > 5) FROM Cliente c JOIN Comprar co ON c.RUN = co.Cliente_id JOIN Venta v ON co.Venta_id = v.ID JOIN Vender ve ON v.ID = ve.Venta_id WHERE c.RUN = p_run_cliente AND DATE_TRUNC('month', ve.Fecha) = DATE_TRUNC('month', CURRENT_DATE) GROUP BY c.RUN; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_ventas_mes_articulo_vendedor() RETURNS TABLE(vendedor_run VARCHAR, producto_id INT, producto_nombre VARCHAR, total_ventas BIGINT) AS $$ BEGIN RETURN QUERY SELECT op.Emprendedor_id, p.ID, p.Nombre, COUNT(co.Venta_id) FROM OfrecerP op JOIN Producto p ON op.Producto_id = p.ID JOIN Comprar co ON p.ID = co.Producto_id JOIN Vender ve ON co.Venta_id = ve.Venta_id WHERE DATE_TRUNC('month', ve.Fecha) = DATE_TRUNC('month', CURRENT_DATE) GROUP BY op.Emprendedor_id, p.ID, p.Nombre; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_volumen_ventas_fin_semana_vs_habiles() RETURNS TABLE(tipo_dia TEXT, cantidad_ventas BIGINT, total_monto NUMERIC) AS $$ BEGIN RETURN QUERY SELECT CASE WHEN EXTRACT(ISODOW FROM ve.Fecha) IN (6, 7) THEN 'Fin de semana' ELSE 'Día hábil' END, COUNT(v.ID), SUM(v.Total)::NUMERIC FROM Venta v JOIN Vender ve ON v.ID = ve.Venta_id GROUP BY CASE WHEN EXTRACT(ISODOW FROM ve.Fecha) IN (6, 7) THEN 'Fin de semana' ELSE 'Día hábil' END; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_variacion_porcentual_ingresos_mensual() RETURNS TABLE(mes_actual_monto NUMERIC, mes_anterior_monto NUMERIC, variacion_porcentual NUMERIC) AS $$ DECLARE v_actual NUMERIC; v_anterior NUMERIC; BEGIN SELECT COALESCE(SUM(v.Total), 0) INTO v_actual FROM Venta v JOIN Vender ve ON v.ID = ve.Venta_id WHERE DATE_TRUNC('month', ve.Fecha) = DATE_TRUNC('month', CURRENT_DATE); SELECT COALESCE(SUM(v.Total), 0) INTO v_anterior FROM Venta v JOIN Vender ve ON v.ID = ve.Venta_id WHERE DATE_TRUNC('month', ve.Fecha) = DATE_TRUNC('month', CURRENT_DATE - INTERVAL '1 month'); RETURN QUERY SELECT v_actual, v_anterior, CASE WHEN v_anterior = 0 THEN 0 ELSE ROUND(((v_actual - v_anterior) / v_anterior) * 100, 2) END; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_ventas_ultimo_trimestre_con_descuento() RETURNS TABLE(venta_id INT, valor_bruto INT, descuento INT, total INT, fecha DATE) AS $$ BEGIN RETURN QUERY SELECT v.ID, v.ValorBruto, v.Descuento, v.Total, ve.Fecha FROM Venta v JOIN Vender ve ON v.ID = ve.Venta_id WHERE v.Descuento > 0 AND ve.Fecha >= CURRENT_DATE - INTERVAL '3 months'; END; $$ LANGUAGE plpgsql;

-- GRUPO 2: Georreferenciacion Logistica
CREATE OR REPLACE FUNCTION fn_ciudades_contrataron_servicio(p_servicio VARCHAR) RETURNS TABLE(comuna_id INT, comuna_nombre VARCHAR) AS $$ BEGIN RETURN QUERY SELECT DISTINCT cm.ID, cm.Nombre FROM Servicio s JOIN Contratar ct ON s.ID = ct.Servicio_id JOIN Registrar r ON ct.Cliente_id = r.Cliente_id JOIN Direccion d ON r.Direccion_id = d.CodPostal JOIN Comuna cm ON d.Comuna_id = cm.ID WHERE s.Nombre ILIKE '%' || p_servicio || '%'; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_ciudades_despachado_producto(p_producto VARCHAR) RETURNS TABLE(comuna_id INT, comuna_nombre VARCHAR) AS $$ BEGIN RETURN QUERY SELECT DISTINCT cm.ID, cm.Nombre FROM Producto p JOIN Comprar co ON p.ID = co.Producto_id JOIN Registrar r ON co.Cliente_id = r.Cliente_id JOIN Direccion d ON r.Direccion_id = d.CodPostal JOIN Comuna cm ON d.Comuna_id = cm.ID WHERE p.Nombre ILIKE '%' || p_producto || '%'; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_productos_vendedor_despacho_pendiente() RETURNS TABLE(vendedor_run VARCHAR, producto_id INT, producto_nombre VARCHAR, venta_id INT) AS $$ BEGIN RETURN QUERY SELECT op.Emprendedor_id, p.ID, p.Nombre, v.ID FROM OfrecerP op JOIN Producto p ON op.Producto_id = p.ID JOIN Comprar co ON p.ID = co.Producto_id JOIN Venta v ON co.Venta_id = v.ID WHERE v.Estado = 'En Preparación'; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_tiempo_promedio_transito_logistico() RETURNS TABLE(empresa_transporte VARCHAR, dias_promedio NUMERIC) AS $$ BEGIN RETURN QUERY SELECT e.Empresa, ROUND(AVG(e.FechaLlegada - e.FechaSalida), 2) FROM Envio e GROUP BY e.Empresa; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_regiones_mayor_volumen_envios_pesados() RETURNS TABLE(region_id INT, region_nombre VARCHAR, total_envios BIGINT) AS $$ BEGIN RETURN QUERY SELECT r.ID, r.Nombre, COUNT(e.Seguimiento) FROM Envio e JOIN Venta v ON e.Seguimiento = v.Despacho JOIN Comprar co ON v.ID = co.Venta_id JOIN Registrar rg ON co.Cliente_id = rg.Cliente_id JOIN Direccion d ON rg.Direccion_id = d.CodPostal JOIN Comuna cm ON d.Comuna_id = cm.ID JOIN Provincia pr ON cm.ID_Provincia = pr.ID JOIN Region r ON pr.ID_Region = r.ID WHERE e.Peso > 10.0 GROUP BY r.ID, r.Nombre ORDER BY COUNT(e.Seguimiento) DESC; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_comunas_clientes_despacho_sin_pasaje_sector() RETURNS TABLE(comuna_id INT, comuna_nombre VARCHAR) AS $$ BEGIN RETURN QUERY SELECT DISTINCT cm.ID, cm.Nombre FROM Cliente c JOIN Registrar rg ON c.RUN = rg.Cliente_id JOIN Direccion d ON rg.Direccion_id = d.CodPostal JOIN Comuna cm ON d.Comuna_id = cm.ID JOIN Comprar co ON c.RUN = co.Cliente_id JOIN Venta v ON co.Venta_id = v.ID WHERE v.Despacho IS NOT NULL AND (d.Pasaje IS NULL OR d.Sector IS NULL); END; $$ LANGUAGE plpgsql;

-- GRUPO 3: Fidelizacion y Valoraciones
CREATE OR REPLACE FUNCTION fn_producto_mas_vendido_por_vendedor() RETURNS TABLE(vendedor_run VARCHAR, producto_id INT, producto_nombre VARCHAR, cantidad_vendida BIGINT) AS $$ BEGIN RETURN QUERY WITH ventas AS (SELECT op.Emprendedor_id, p.ID AS p_id, p.Nombre AS p_nom, COUNT(co.Venta_id) AS cnt, RANK() OVER (PARTITION BY op.Emprendedor_id ORDER BY COUNT(co.Venta_id) DESC) as rk FROM OfrecerP op JOIN Producto p ON op.Producto_id = p.ID JOIN Comprar co ON p.ID = co.Producto_id GROUP BY op.Emprendedor_id, p.ID, p.Nombre) SELECT Emprendedor_id, p_id, p_nom, cnt FROM ventas WHERE rk = 1; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_servicio_mas_contratado_por_vendedor() RETURNS TABLE(vendedor_run VARCHAR, servicio_id INT, servicio_nombre VARCHAR, cantidad_contratada BIGINT) AS $$ BEGIN RETURN QUERY WITH contrat AS (SELECT os.Emprendedor_id, s.ID AS s_id, s.Nombre AS s_nom, COUNT(ct.Venta_id) AS cnt, RANK() OVER (PARTITION BY os.Emprendedor_id ORDER BY COUNT(ct.Venta_id) DESC) as rk FROM OfrecerS os JOIN Servicio s ON os.Servicio_id = s.ID JOIN Contratar ct ON s.ID = ct.Servicio_id GROUP BY os.Emprendedor_id, s.ID, s.Nombre) SELECT Emprendedor_id, s_id, s_nom, cnt FROM contrat WHERE rk = 1; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_consultas_sin_responder_producto(p_producto_id INT) RETURNS INT AS $$ DECLARE v_cant INT; BEGIN SELECT COUNT(pp.Pregunta_id) INTO v_cant FROM PreguntarP pp LEFT JOIN ComunicarP cp ON pp.Producto_id = cp.Producto_id AND pp.Cliente_id = cp.Cliente_id AND pp.Emprendedor_id = cp.Emprendedor_id WHERE pp.Producto_id = p_producto_id AND cp.Mensajeria_id IS NULL; RETURN COALESCE(v_cant, 0); END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_productos_vendedor_calificacion_alta(p_run_vendedor VARCHAR) RETURNS TABLE(producto_id INT, producto_nombre VARCHAR, promedio_puntaje NUMERIC) AS $$ BEGIN RETURN QUERY SELECT p.ID, p.Nombre, ROUND(AVG(c.Puntaje), 2) FROM OfrecerP op JOIN Producto p ON op.Producto_id = p.ID JOIN CalificarP cp ON p.ID = cp.Producto_id JOIN Calificacion c ON cp.Calificacion_id = c.ID WHERE op.Emprendedor_id = p_run_vendedor GROUP BY p.ID, p.Nombre HAVING AVG(c.Puntaje) >= 4.0; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_emprendedores_promedio_calificacion_baja() RETURNS TABLE(vendedor_run VARCHAR, promedio_puntaje NUMERIC) AS $$ BEGIN RETURN QUERY SELECT op.Emprendedor_id, ROUND(AVG(c.Puntaje), 2) FROM OfrecerP op JOIN CalificarP cp ON op.Producto_id = cp.Producto_id JOIN Calificacion c ON cp.Calificacion_id = c.ID GROUP BY op.Emprendedor_id HAVING AVG(c.Puntaje) < 3.0; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_emprendedores_sin_calificacion_ultimo_semestre() RETURNS TABLE(vendedor_run VARCHAR, nombre TEXT) AS $$ BEGIN RETURN QUERY SELECT e.RUN, (e.Nombre || ' ' || e.Apellido)::TEXT FROM Emprendedor e JOIN OfrecerS os ON e.RUN = os.Emprendedor_id LEFT JOIN CalificarS cs ON os.Servicio_id = cs.Servicio_id AND cs.Fecha >= CURRENT_DATE - INTERVAL '6 months' WHERE cs.Calificacion_id IS NULL; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_reseñas_clave_calidad() RETURNS TABLE(calificacion_id INT, comentario TEXT) AS $$ BEGIN RETURN QUERY SELECT c.ID, c.Comentario FROM Calificacion c WHERE c.Comentario ILIKE '%excelente%' OR c.Comentario ILIKE '%recomendado%' OR c.Comentario ILIKE '%deficiente%'; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_clientes_mas_diez_calificaciones() RETURNS TABLE(cliente_run VARCHAR, cliente_nombre TEXT, total_calificaciones BIGINT) AS $$ BEGIN RETURN QUERY SELECT c.RUN, (c.Nombre || ' ' || c.Apellido)::TEXT, COUNT(cp.Calificacion_id) FROM Cliente c JOIN CalificarP cp ON c.RUN = cp.Cliente_id GROUP BY c.RUN, c.Nombre, c.Apellido HAVING COUNT(cp.Calificacion_id) > 10 ORDER BY COUNT(cp.Calificacion_id) DESC; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_tiempo_promedio_respuesta_preguntas() RETURNS TABLE(vendedor_run VARCHAR, horas_promedio NUMERIC) AS $$ BEGIN RETURN QUERY SELECT pp.Emprendedor_id, ROUND(AVG(EXTRACT(EPOCH FROM (cp.Fecha - pp.Fecha)) / 3600.0), 2) FROM PreguntarP pp JOIN ComunicarP cp ON pp.Producto_id = cp.Producto_id AND pp.Cliente_id = cp.Cliente_id AND pp.Emprendedor_id = cp.Emprendedor_id GROUP BY pp.Emprendedor_id; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_mensajeria_sin_replica_48h() RETURNS TABLE(mensajeria_id INT, cliente_id VARCHAR, emprendedor_id VARCHAR, fecha TIMESTAMP) AS $$ BEGIN RETURN QUERY SELECT m.ID, cp.Cliente_id, cp.Emprendedor_id, cp.Fecha FROM Mensajeria m JOIN ComunicarP cp ON m.ID = cp.Mensajeria_id WHERE NOT EXISTS (SELECT 1 FROM ComunicarP cp2 WHERE cp2.Producto_id = cp.Producto_id AND cp2.Cliente_id = cp.Cliente_id AND cp2.Fecha > cp.Fecha) AND CURRENT_TIMESTAMP - cp.Fecha > INTERVAL '48 hours'; END; $$ LANGUAGE plpgsql;

-- GRUPO 4: JSON
CREATE OR REPLACE FUNCTION fn_json_material_principal_vestuario() RETURNS TABLE(producto_id INT, nombre VARCHAR, material_principal TEXT) AS $$ BEGIN RETURN QUERY SELECT p.ID, p.Nombre, (p.Descripción->>'Material principal')::TEXT FROM Producto p JOIN Categoría cat ON p.Categoria_id = cat.ID WHERE cat.Nombre ILIKE '%Vestuario%'; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_json_servicios_modalidad_remoto() RETURNS TABLE(servicio_id INT, nombre VARCHAR, modalidad TEXT) AS $$ BEGIN RETURN QUERY SELECT s.ID, s.Nombre, (s.Descripcion->>'Modalidad')::TEXT FROM Servicio s WHERE (s.Descripcion->>'Modalidad') ILIKE '%Remoto%'; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_json_peso_promedio_inventario() RETURNS NUMERIC AS $$ DECLARE v_peso_prom NUMERIC; BEGIN SELECT ROUND(AVG((Descripción->>'Peso')::NUMERIC), 2) INTO v_peso_prom FROM Producto WHERE (Descripción->>'Peso') IS NOT NULL; RETURN COALESCE(v_peso_prom, 0); END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_json_productos_tecno_sin_garantia() RETURNS TABLE(producto_id INT, nombre VARCHAR) AS $$ BEGIN RETURN QUERY SELECT p.ID, p.Nombre FROM Producto p JOIN Categoría cat ON p.Categoria_id = cat.ID WHERE cat.Nombre ILIKE '%Tecnología%' AND ((p.Descripción->>'Garantía') IS NULL OR (p.Descripción->>'Garantía') = ''); END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE VIEW vw_variantes_json AS SELECT ID AS producto_id, Nombre AS producto_nombre, Descripción->>'Color' AS color, Descripción->>'Talla' AS talla, Descripción->>'Material principal' AS material FROM Producto;
CREATE OR REPLACE FUNCTION fn_vista_desnormalizar_variantes_json() RETURNS TABLE(producto_id INT, producto_nombre VARCHAR, color TEXT, talla TEXT, material TEXT) AS $$ BEGIN RETURN QUERY SELECT * FROM vw_variantes_json; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_json_productos_exceden_volumen_logistico() RETURNS TABLE(producto_id INT, nombre VARCHAR, volumen NUMERIC) AS $$ BEGIN RETURN QUERY SELECT p.ID, p.Nombre, ((p.Descripción->>'Ancho')::NUMERIC * (p.Descripción->>'Alto')::NUMERIC * (p.Descripción->>'Fondo')::NUMERIC) FROM Producto p WHERE ((p.Descripción->>'Ancho')::NUMERIC * (p.Descripción->>'Alto')::NUMERIC * (p.Descripción->>'Fondo')::NUMERIC) > 50000; END; $$ LANGUAGE plpgsql;

-- GRUPO 5: Conjuntos y Correlacionadas
CREATE OR REPLACE FUNCTION fn_servicios_no_contratados_mes(p_mes INT, p_anio INT) RETURNS TABLE(servicio_id INT, nombre VARCHAR) AS $$ BEGIN RETURN QUERY SELECT s.ID, s.Nombre FROM Servicio s WHERE s.ID NOT IN (SELECT ct.Servicio_id FROM Contratar ct JOIN Vender ve ON ct.Venta_id = ve.Venta_id WHERE EXTRACT(MONTH FROM ve.Fecha) = p_mes AND EXTRACT(YEAR FROM ve.Fecha) = p_anio); END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_total_pedidos_vendedor_categoria(p_vendedor_id VARCHAR, p_categoria_id INT) RETURNS BIGINT AS $$ DECLARE v_total BIGINT; BEGIN SELECT COUNT(co.Venta_id) INTO v_total FROM OfrecerP op JOIN Producto p ON op.Producto_id = p.ID JOIN Comprar co ON p.ID = co.Producto_id WHERE op.Emprendedor_id = p_vendedor_id AND p.Categoria_id = p_categoria_id; RETURN COALESCE(v_total, 0); END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_clientes_vendedor_negocio(p_vendedor_id VARCHAR) RETURNS TABLE(cliente_run VARCHAR, cliente_nombre TEXT) AS $$ BEGIN RETURN QUERY SELECT DISTINCT c.RUN, (c.Nombre || ' ' || c.Apellido)::TEXT FROM Cliente c JOIN Comprar co ON c.RUN = co.Cliente_id JOIN OfrecerP op ON co.Producto_id = op.Producto_id WHERE op.Emprendedor_id = p_vendedor_id; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_usuarios_rol_dual_cliente_emprendedor() RETURNS TABLE(run VARCHAR, nombre TEXT) AS $$ BEGIN RETURN QUERY SELECT c.RUN, (c.Nombre || ' ' || c.Apellido)::TEXT FROM Cliente c WHERE c.RUN IN (SELECT e.RUN FROM Emprendedor e); END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_clientes_wishlist_sin_compras() RETURNS TABLE(cliente_run VARCHAR, cliente_nombre TEXT) AS $$ BEGIN RETURN QUERY SELECT DISTINCT c.RUN, (c.Nombre || ' ' || c.Apellido)::TEXT FROM Cliente c JOIN DesearP dp ON c.RUN = dp.Cliente_id WHERE c.RUN NOT IN (SELECT DISTINCT co.Cliente_id FROM Comprar co); END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_categorias_principales_sin_subcategorias_ni_productos() RETURNS TABLE(categoria_id INT, nombre VARCHAR) AS $$ BEGIN RETURN QUERY SELECT cat.ID, cat.Nombre FROM Categoría cat WHERE cat.Categoria_id IS NULL AND NOT EXISTS (SELECT 1 FROM Categoría sub WHERE sub.Categoria_id = cat.ID) AND NOT EXISTS (SELECT 1 FROM Producto p WHERE p.Categoria_id = cat.ID); END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_clientes_compraron_todas_categorias() RETURNS TABLE(cliente_run VARCHAR, cliente_nombre TEXT) AS $$ BEGIN RETURN QUERY SELECT c.RUN, (c.Nombre || ' ' || c.Apellido)::TEXT FROM Cliente c JOIN Comprar co ON c.RUN = co.Cliente_id JOIN Producto p ON co.Producto_id = p.ID JOIN Categoría cat ON p.Categoria_id = cat.ID GROUP BY c.RUN, c.Nombre, c.Apellido HAVING COUNT(DISTINCT cat.ID) = (SELECT COUNT(*) FROM Categoría WHERE Categoria_id IS NULL); END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_servicios_multiples_regiones() RETURNS TABLE(servicio_id INT, servicio_nombre VARCHAR, cantidad_regiones BIGINT) AS $$ BEGIN RETURN QUERY SELECT s.ID, s.Nombre, COUNT(DISTINCT pr.ID_Region) FROM Servicio s JOIN OfrecerS os ON s.ID = os.Servicio_id JOIN TieneDirE tde ON os.Emprendedor_id = tde.Emprendedor_id JOIN Direccion d ON tde.Direccion_id = d.CodPostal JOIN Comuna cm ON d.Comuna_id = cm.ID JOIN Provincia pr ON cm.ID_Provincia = pr.ID GROUP BY s.ID, s.Nombre HAVING COUNT(DISTINCT pr.ID_Region) > 1; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_productos_frecuentemente_juntos() RETURNS TABLE(producto1_id INT, producto2_id INT, veces_juntos BIGINT) AS $$ BEGIN RETURN QUERY SELECT c1.Producto_id, c2.Producto_id, COUNT(*) FROM Comprar c1 JOIN Comprar c2 ON c1.Venta_id = c2.Venta_id AND c1.Producto_id < c2.Producto_id GROUP BY c1.Producto_id, c2.Producto_id ORDER BY COUNT(*) DESC; END; $$ LANGUAGE plpgsql;

-- GRUPO 6: Inventario y Finanzas
CREATE OR REPLACE FUNCTION fn_productos_devoluciones_por_cliente() RETURNS TABLE(cliente_id VARCHAR, producto_id INT, motivo TEXT) AS $$ BEGIN RETURN QUERY SELECT co.Cliente_id, co.Producto_id, d.Medio FROM Comprar co JOIN Devolucion d ON co.Devolucion_id = d.ID WHERE co.Devolucion_id IS NOT NULL; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_productos_ofertas_vigentes() RETURNS TABLE(producto_id INT, producto_nombre VARCHAR, precio_original INT, precio_oferta INT) AS $$ BEGIN RETURN QUERY SELECT p.ID, p.Nombre, pos.Precio, o.Precio FROM Producto p JOIN Poseer pos ON p.ID = pos.Producto_id JOIN OfertarP op ON p.ID = op.Producto_id JOIN Oferta o ON op.Oferta_id = o.ID WHERE CURRENT_DATE BETWEEN op.Finicio AND COALESCE(op.Ffin, '2099-12-31'::DATE); END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_volumen_capital_reintegrado_devoluciones() RETURNS NUMERIC AS $$ DECLARE v_total NUMERIC; BEGIN SELECT COALESCE(SUM(d.Valor), 0) INTO v_total FROM Devolucion d JOIN Comprar co ON d.ID = co.Devolucion_id WHERE EXTRACT(YEAR FROM co.FechaDevolucion) = EXTRACT(YEAR FROM CURRENT_DATE); RETURN v_total; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_wishlist_oferta_expira_24h() RETURNS TABLE(cliente_id VARCHAR, producto_id INT, finicio DATE, ffin DATE) AS $$ BEGIN RETURN QUERY SELECT dp.Cliente_id, dp.Producto_id, op.Finicio, op.Ffin FROM DesearP dp JOIN OfertarP op ON dp.Producto_id = op.Producto_id WHERE op.Ffin BETWEEN CURRENT_DATE AND CURRENT_DATE + INTERVAL '1 day'; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_tasa_devoluciones_por_emprendedor() RETURNS TABLE(vendedor_run VARCHAR, ventas_exitosas BIGINT, devoluciones BIGINT, tasa NUMERIC) AS $$ BEGIN RETURN QUERY SELECT op.Emprendedor_id, COUNT(co.Venta_id), COUNT(co.Devolucion_id), CASE WHEN COUNT(co.Venta_id) = 0 THEN 0 ELSE ROUND((COUNT(co.Devolucion_id)::NUMERIC / COUNT(co.Venta_id)::NUMERIC) * 100, 2) END FROM OfrecerP op JOIN Comprar co ON op.Producto_id = co.Producto_id GROUP BY op.Emprendedor_id; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_productos_mas_tres_variantes_stock_alto() RETURNS TABLE(producto_id INT, producto_nombre VARCHAR, stock_total BIGINT) AS $$ BEGIN RETURN QUERY SELECT p.ID, p.Nombre, SUM(op.Stock)::BIGINT FROM Producto p JOIN OfrecerP op ON p.ID = op.Producto_id JOIN Poseer pos ON p.ID = pos.Producto_id GROUP BY p.ID, p.Nombre HAVING COUNT(DISTINCT pos.Caracteristicas_id) >= 1 AND SUM(op.Stock) > 50; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_ventas_canceladas_transferencia() RETURNS TABLE(venta_id INT, cliente_id VARCHAR, total INT) AS $$ BEGIN RETURN QUERY SELECT v.ID, co.Cliente_id, v.Total FROM Venta v JOIN Vender ve ON v.ID = ve.Venta_id JOIN MedioPago mp ON ve.MedioPago_id = mp.ID JOIN Comprar co ON v.ID = co.Venta_id WHERE v.Estado = 'Cancelada' OR mp.Tipo ILIKE '%Transferencia%'; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE VIEW vw_wishlist_vs_conversion AS SELECT p.ID AS producto_id, p.Nombre AS producto_nombre, COUNT(DISTINCT dp.Cliente_id) AS deseados, COUNT(DISTINCT co.Cliente_id) AS compras, CASE WHEN COUNT(DISTINCT dp.Cliente_id) = 0 THEN 0 ELSE ROUND((COUNT(DISTINCT co.Cliente_id)::NUMERIC / COUNT(DISTINCT dp.Cliente_id)::NUMERIC) * 100, 2) END AS conversion FROM Producto p LEFT JOIN DesearP dp ON p.ID = dp.Producto_id LEFT JOIN Comprar co ON p.ID = co.Producto_id GROUP BY p.ID, p.Nombre;
CREATE OR REPLACE FUNCTION fn_vista_inteligencia_wishlist_vs_conversion() RETURNS TABLE(producto_id INT, producto_nombre VARCHAR, deseados BIGINT, compras BIGINT, conversion NUMERIC) AS $$ BEGIN RETURN QUERY SELECT * FROM vw_wishlist_vs_conversion; END; $$ LANGUAGE plpgsql;

-- GRUPO 7: Demografia y Validaciones
CREATE OR REPLACE FUNCTION fn_edad_cronologica_clientes() RETURNS TABLE(cliente_run VARCHAR, cliente_nombre TEXT, edad_anios INT, es_menor BOOLEAN) AS $$ BEGIN RETURN QUERY SELECT c.RUN, (c.Nombre || ' ' || c.Apellido)::TEXT, EXTRACT(YEAR FROM AGE(CURRENT_DATE, c.FechaNac))::INT, (EXTRACT(YEAR FROM AGE(CURRENT_DATE, c.FechaNac)) < 18) FROM Cliente c; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_intentos_contratacion_servicio_menores_edad() RETURNS TABLE(cliente_run VARCHAR, servicio_id INT, servicio_nombre VARCHAR, edad_cliente INT) AS $$ BEGIN RETURN QUERY SELECT c.RUN, s.ID, s.Nombre, EXTRACT(YEAR FROM AGE(CURRENT_DATE, c.FechaNac))::INT FROM Cliente c JOIN Contratar ct ON c.RUN = ct.Cliente_id JOIN Servicio s ON ct.Servicio_id = s.ID WHERE EXTRACT(YEAR FROM AGE(CURRENT_DATE, c.FechaNac)) < 18 AND (s.Descripcion->>'RestriccionEdad') IS NOT NULL; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_segmentacion_etaria_decenales() RETURNS TABLE(rango_etario TEXT, cantidad_clientes BIGINT) AS $$ BEGIN RETURN QUERY SELECT (FLOOR(EXTRACT(YEAR FROM AGE(CURRENT_DATE, c.FechaNac)) / 10) * 10)::TEXT || '-' || (FLOOR(EXTRACT(YEAR FROM AGE(CURRENT_DATE, c.FechaNac)) / 10) * 10 + 9)::TEXT AS rango, COUNT(*) FROM Cliente c GROUP BY FLOOR(EXTRACT(YEAR FROM AGE(CURRENT_DATE, c.FechaNac)) / 10) ORDER BY rango; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_correos_anomalias_estructurales() RETURNS TABLE(correo VARCHAR, motivo TEXT) AS $$ BEGIN RETURN QUERY SELECT c.Correo, 'Formato inválido'::TEXT FROM Correo c WHERE c.Correo NOT LIKE '%@%.%'; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_emprendedores_empresa_sin_web() RETURNS TABLE(emprendedor_run VARCHAR, empresa_rut VARCHAR, empresa_nombre VARCHAR) AS $$ BEGIN RETURN QUERY SELECT e.RUN, emp.RUT, emp.Nombre FROM Emprendedor e JOIN Empresa emp ON e.Empresa_id = emp.RUT WHERE e.Web IS NULL OR e.Web = ''; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_direcciones_despacho_avenida_camino() RETURNS TABLE(direccion_id INT, calle VARCHAR, numero INT) AS $$ BEGIN RETURN QUERY SELECT d.CodPostal, d.Calle, d.Numero FROM Direccion d WHERE d.Calle ILIKE 'Avenida%' OR d.Calle ILIKE 'Camino%'; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_emprendedores_mayores_60_servicio_educativo() RETURNS TABLE(emprendedor_run VARCHAR, emprendedor_nombre TEXT, edad INT) AS $$ BEGIN RETURN QUERY SELECT e.RUN, (e.Nombre || ' ' || e.Apellido)::TEXT, EXTRACT(YEAR FROM AGE(CURRENT_DATE, e.FechaNac))::INT FROM Emprendedor e JOIN OfrecerS os ON e.RUN = os.Emprendedor_id JOIN Servicio s ON os.Servicio_id = s.ID JOIN Categoría cat ON s.Categoria_id = cat.ID WHERE EXTRACT(YEAR FROM AGE(CURRENT_DATE, e.FechaNac)) > 60 AND cat.Nombre ILIKE '%Educat%'; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_medios_pago_visa_mastercard() RETURNS TABLE(medio_id INT, tipo VARCHAR, marca VARCHAR) AS $$ BEGIN RETURN QUERY SELECT mp.ID, mp.Tipo, mp.Marca FROM MedioPago mp WHERE mp.Marca ILIKE '%Visa%' OR mp.Marca ILIKE '%MasterCard%'; END; $$ LANGUAGE plpgsql;

-- GRUPO 8: Vistas Logicas e Indicadores
CREATE OR REPLACE VIEW vw_factura_fiscal_cliente AS SELECT v.ID AS venta_id, v.ValorBruto AS valor_neto, ROUND(v.ValorBruto * (v.IVA / 100.0), 2) AS impuesto_iva, COALESCE(v.Descuento, 0) AS descuento, COALESCE(e.Valor::NUMERIC, 0) AS recargo_envio, v.Total AS total_pagado FROM Venta v LEFT JOIN Envio e ON v.Despacho = e.Seguimiento;
CREATE OR REPLACE FUNCTION fn_factura_fiscal_cliente(p_venta_id INT) RETURNS TABLE(venta_id INT, valor_neto INT, impuesto_iva NUMERIC, descuento INT, recargo_envio NUMERIC, total_pagado INT) AS $$ BEGIN RETURN QUERY SELECT * FROM vw_factura_fiscal_cliente f WHERE f.venta_id = p_venta_id; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE VIEW vw_inventario_critico AS SELECT p.ID AS producto_id, p.Nombre AS producto_nombre, op.Stock AS stock_disponible FROM Producto p JOIN OfrecerP op ON p.ID = op.Producto_id WHERE op.Stock < 10;
CREATE OR REPLACE FUNCTION fn_inventario_critico() RETURNS TABLE(producto_id INT, producto_nombre VARCHAR, stock_disponible INT) AS $$ BEGIN RETURN QUERY SELECT * FROM vw_inventario_critico; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE VIEW vw_rendimiento_emprendedores AS SELECT op.Emprendedor_id AS emprendedor_run, SUM(v.Total) AS facturacion_trimestral, CASE WHEN SUM(v.Total) >= 1000000 THEN 'Alto Rendimiento' WHEN SUM(v.Total) >= 500000 THEN 'Rendimiento Medio' ELSE 'Bajo Rendimiento' END AS categoria_rendimiento FROM OfrecerP op JOIN Comprar co ON op.Producto_id = co.Producto_id JOIN Venta v ON co.Venta_id = v.ID JOIN Vender ve ON v.ID = ve.Venta_id WHERE ve.Fecha >= CURRENT_DATE - INTERVAL '3 months' GROUP BY op.Emprendedor_id;
CREATE OR REPLACE FUNCTION fn_rendimiento_emprendedores() RETURNS TABLE(emprendedor_run VARCHAR, facturacion_trimestral BIGINT, categoria_rendimiento TEXT) AS $$ BEGIN RETURN QUERY SELECT * FROM vw_rendimiento_emprendedores; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE VIEW vw_life_time_value_cliente AS SELECT c.RUN AS cliente_run, (c.Nombre || ' ' || c.Apellido)::TEXT AS cliente_nombre, COALESCE(SUM(v.Total), 0) AS ltv_total_acumulado, COUNT(DISTINCT v.ID) AS total_transacciones FROM Cliente c LEFT JOIN Comprar co ON c.RUN = co.Cliente_id LEFT JOIN Venta v ON co.Venta_id = v.ID GROUP BY c.RUN, c.Nombre, c.Apellido;
CREATE OR REPLACE FUNCTION fn_life_time_value_cliente() RETURNS TABLE(cliente_run VARCHAR, cliente_nombre TEXT, ltv_total_acumulado BIGINT, total_transacciones BIGINT) AS $$ BEGIN RETURN QUERY SELECT * FROM vw_life_time_value_cliente; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE VIEW vw_categorias_jerarquica AS WITH RECURSIVE arbol_cat AS (SELECT ID, Nombre, Categoria_id, 1 AS nivel, Nombre::TEXT AS ruta FROM Categoría WHERE Categoria_id IS NULL UNION ALL SELECT c.ID, c.Nombre, c.Categoria_id, ac.nivel + 1, (ac.ruta || ' > ' || c.Nombre)::TEXT FROM Categoría c JOIN arbol_cat ac ON c.Categoria_id = ac.ID) SELECT ID AS categoria_id, Nombre AS categoria_nombre, Categoria_id AS padre_id, nivel, ruta FROM arbol_cat;
CREATE OR REPLACE FUNCTION fn_categorias_jerarquica() RETURNS TABLE(categoria_id INT, categoria_nombre VARCHAR, padre_id INT, nivel INT, ruta TEXT) AS $$ BEGIN RETURN QUERY SELECT * FROM vw_categorias_jerarquica; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE VIEW vw_utilidades_operativas AS SELECT SUM(v.ValorBruto) AS total_ventas_brutas, ROUND(SUM(v.ValorBruto) * 0.05, 2) AS comision_plataforma FROM Venta v;
CREATE OR REPLACE FUNCTION fn_utilidades_operativas() RETURNS TABLE(total_ventas_brutas BIGINT, comision_plataforma NUMERIC) AS $$ BEGIN RETURN QUERY SELECT * FROM vw_utilidades_operativas; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE VIEW vw_empresas_geoespacial AS SELECT emp.Giro, COUNT(DISTINCT emp.RUT) AS cantidad_empresas, SUM(DISTINCT cm.Superficie) AS superficie FROM Empresa emp JOIN TieneDirEmpresa tde ON emp.RUT = tde.Empresa_ID JOIN Direccion d ON tde.Direccion_id = d.CodPostal JOIN Comuna cm ON d.Comuna_id = cm.ID GROUP BY emp.Giro;
CREATE OR REPLACE FUNCTION fn_empresas_geoespacial() RETURNS TABLE(giro VARCHAR, cantidad_empresas BIGINT, superficie BIGINT) AS $$ BEGIN RETURN QUERY SELECT * FROM vw_empresas_geoespacial; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE VIEW vw_monitoreo_nuevos_clientes AS SELECT ROUND(COUNT(*)::NUMERIC / 30.0, 2) AS promedio_diario_nuevos_registros FROM Cliente;
CREATE OR REPLACE FUNCTION fn_monitoreo_nuevos_clientes() RETURNS NUMERIC AS $$ DECLARE v_prom NUMERIC; BEGIN SELECT promedio_diario_nuevos_registros INTO v_prom FROM vw_monitoreo_nuevos_clientes; RETURN v_prom; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION fn_auditoria_consistencia_numerica_ventas() RETURNS TABLE(venta_id INT, total_registrado INT, total_calculado NUMERIC, es_consistente BOOLEAN) AS $$ BEGIN RETURN QUERY SELECT v.ID, v.Total, ROUND(v.ValorBruto * (1 + v.IVA / 100.0)) - COALESCE(v.Descuento, 0) AS calc, (v.Total = (ROUND(v.ValorBruto * (1 + v.IVA / 100.0)) - COALESCE(v.Descuento, 0))) AS ok FROM Venta v; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE VIEW vw_catalogo_unificado AS SELECT 'Producto' AS tipo_item, p.ID AS item_id, p.Nombre AS item_nombre, cat.Nombre AS categoria_nombre, op.Stock AS disponibilidad_stock, pos.Precio AS precio FROM Producto p JOIN Categoría cat ON p.Categoria_id = cat.ID LEFT JOIN OfrecerP op ON p.ID = op.Producto_id LEFT JOIN Poseer pos ON p.ID = pos.Producto_id UNION ALL SELECT 'Servicio' AS tipo_item, s.ID AS item_id, s.Nombre AS item_nombre, cat.Nombre AS categoria_nombre, 999 AS disponibilidad_stock, s.Precio AS precio FROM Servicio s JOIN Categoría cat ON s.Categoria_id = cat.ID;
CREATE OR REPLACE FUNCTION fn_catalogo_unificado() RETURNS TABLE(tipo_item TEXT, item_id INT, item_nombre VARCHAR, categoria_nombre VARCHAR, disponibilidad_stock INT, precio INT) AS $$ BEGIN RETURN QUERY SELECT * FROM vw_catalogo_unificado; END; $$ LANGUAGE plpgsql;